// Get original email fields from IMAP trigger
const email = $('Email Trigger (IMAP)').first().json;

// Get clean body text from Markdown node
const bodyText = $input.first().json.data || email.text || '';

// Extract sender address cleanly
let fromEmail = '';
let fromName  = '';
if (email.from && email.from.value && email.from.value[0]) {
  fromEmail = email.from.value[0].address || '';
  fromName  = email.from.value[0].name    || '';
} else {
  fromEmail = String(email.from || '');
}

return [{
  json: {
    message_id:  email.messageId || ('MSG-' + Date.now()),
    from_email:  fromEmail,
    from_name:   fromName,
    subject:     email.subject  || '(no subject)',
    body_text:   bodyText.substring(0, 3000),
    received_at: email.date    || new Date().toISOString()
  }
}];

