// Pull email data from the extraction node
const emailData = $('Code - Extract Email Data').first().json;

// Pull OpenAI classification result
const openaiResult = $input.first().json;
const rawIntent = openaiResult.choices?.[0]?.message?.content?.trim().toLowerCase() || 'general';

// Validate against allowed categories
const validIntents = ['order_issue', 'refund_request', 'product_help', 'delivery', 'general'];
const intent = validIntents.includes(rawIntent) ? rawIntent : 'general';

// Generate a unique ticket ID
const ticketId = 'TKT-' + Date.now();

return [{
  json: {
    ticket_id:   ticketId,
    from_email:  emailData.from_email,
    from_name:   emailData.from_name,
    subject:     emailData.subject,
    body_text:   emailData.body_text,
    message_id:  emailData.message_id,
    intent:      intent,
    status:      'open',
    ai_draft:    null,
    received_at: emailData.received_at
  }
}];
